<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{login}from'../api/auth';import{useUserStore}from'../stores/user';const router=useRouter(),user=useUserStore(),busy=ref(false),form=reactive({username:'',password:''});async function submit(){if(!/^[\w.-]{3,32}$/.test(form.username))return ElMessage.warning('用户名需为 3–32 位字母、数字、点、横线或下划线');if(form.password.length<6)return ElMessage.warning('密码至少需要 6 位');busy.value=true;try{const r:any=await login(form);const data=r.data||r;localStorage.setItem('ftb_token',data.token||data.accessToken||'');user.setUser(data.user||{username:form.username,role:data.role||'USER'});router.push('/tree')}finally{busy.value=false}}</script>
<template><div class="login-page"><section class="login-art"><div class="brand"><span class="brand-mark">F</span><span>Folio<span class="brand-light">Tree</span></span></div><div><h1>让文件与目录，<br>一目了然。</h1><p>在一个清晰的空间里浏览、搜索和管理你的文件系统。</p></div><small>FILE SYSTEM · STRUCTURE · INSIGHT</small></section><section class="login-box"><h2>欢迎回来</h2><p>登录以继续使用目录工作台</p><form @submit.prevent="submit"><div class="form-row"><label>用户名</label><input v-model.trim="form.username" class="field" placeholder="输入用户名" autocomplete="username"></div><div class="form-row"><label>密码</label><input v-model="form.password" class="field" type="password" placeholder="输入密码" autocomplete="current-password"></div><button class="btn" :disabled="busy">{{busy?'正在登录…':'登录工作台'}}</button></form><div class="sub-link">还没有账号？ <router-link to="/register">创建账号</router-link></div></section></div></template>
